from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import numpy as np
import torch
from torch.utils.data import Dataset


class CCSDAmplitudeDataset(Dataset):
    """Load RHF-CCSD amplitudes generated by ``generate_rhf_dataset.py``.

    Each molecule is a single ``<name>.npz`` containing:
        t2            (nocc, nocc, nvirt, nvirt)  restricted spatial amplitudes
        t1            (nocc, nvirt)
        orb_energies  (norb,)                      active RHF eigenvalues
        mo_coeff      (nao, norb)                  active MO coefficients
        ao_Z, ao_l    (nao,)                        per-AO atom charge / ang. mom.
        nocc, nvirt, norb, ...

    For the reconstruction-loss formulation the *target* is t2 itself (the model
    outputs its own gauge of U and Z), so no precomputed LUCJ targets are needed.

    A small ``_index.json`` (name -> [norb, nocc, nvirt]) is cached in the data
    directory so the bucket sampler can read sizes without opening every file.
    """

    def __init__(self, data_dir: str | Path, species_filter: str | None = None,
                 n_reps: int = 2, targets_dir: str | Path | None = None) -> None:
        self.data_dir = Path(data_dir)
        self.n_reps = n_reps
        # Optional DF (Z, kappa) targets for the warm-start / anti-collapse term.
        self.targets_dir = Path(targets_dir) if targets_dir is not None else None

        allowed: set[str] | None = None
        if species_filter == "TS":
            allowed = {"_TS"}
        elif species_filter == "RP":
            allowed = {"_R", "_P"}

        index = self._load_or_build_index()

        self.names: list[str] = []
        self._norbs: list[int] = []
        self._noccs: list[int] = []
        self._nvirts: list[int] = []
        for name in sorted(index.keys()):
            if allowed is not None:
                suffix = "_" + name.rsplit("_", 1)[-1]
                if suffix not in allowed:
                    continue
            # if using targets, require the target file to exist
            if self.targets_dir is not None and not (self.targets_dir / f"{name}.npz").exists():
                continue
            norb, nocc, nvirt = index[name]
            self.names.append(name)
            self._norbs.append(norb)
            self._noccs.append(nocc)
            self._nvirts.append(nvirt)

    def _load_or_build_index(self) -> dict[str, list[int]]:
        index_path = self.data_dir / "_index.json"
        if index_path.exists():
            with open(index_path) as f:
                return json.load(f)
        index: dict[str, list[int]] = {}
        for f in sorted(self.data_dir.glob("*.npz")):
            try:
                d = np.load(f)
                index[f.stem] = [int(d["norb"]), int(d["nocc"]), int(d["nvirt"])]
            except Exception:
                continue
        with open(index_path, "w") as f:
            json.dump(index, f)
        return index

    def get_norb(self, idx: int) -> int:
        return self._norbs[idx]

    def __len__(self) -> int:
        return len(self.names)

    def __getitem__(self, idx: int) -> dict[str, Any]:
        name = self.names[idx]
        d = np.load(self.data_dir / f"{name}.npz")

        nocc = int(d["nocc"]); nvirt = int(d["nvirt"]); norb = int(d["norb"])
        t2 = d["t2"].astype(np.float32)
        orb_energies = d["orb_energies"].astype(np.float32)
        # stored as (nao, norb) -> model wants (norb, nao)
        mo_coeff = d["mo_coeff"].astype(np.float32).T
        ao_Z = d["ao_Z"].astype(np.float32)
        ao_l = d["ao_l"].astype(np.float32)
        nbasis = mo_coeff.shape[1]

        sample = {
            "t2": torch.from_numpy(t2),
            "orb_energies": torch.from_numpy(orb_energies),
            "mo_coeffs": torch.from_numpy(mo_coeff),
            "ao_Z": torch.from_numpy(ao_Z),
            "ao_l": torch.from_numpy(ao_l),
            "nocc": nocc,
            "nvirt": nvirt,
            "norb": norb,
            "nbasis": nbasis,
            "n_reps": self.n_reps,
            "name": name,
        }

        if self.targets_dir is not None:
            tg = np.load(self.targets_dir / f"{name}.npz")
            sample["z_target"] = torch.from_numpy(tg["Z"].astype(np.float32))
            sample["kappa_real_target"] = torch.from_numpy(tg["kappa_real"].astype(np.float32))
            sample["kappa_imag_target"] = torch.from_numpy(tg["kappa_imag"].astype(np.float32))
        return sample

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(data_dir={self.data_dir!r}, n={len(self)})"

    @staticmethod
    def collate_fn(batch: list[dict[str, Any]]) -> dict[str, Any]:
        max_nocc = max(s["nocc"] for s in batch)
        max_nvirt = max(s["nvirt"] for s in batch)
        max_norb = max(s["norb"] for s in batch)
        max_nbasis = max(s["nbasis"] for s in batch)
        B = len(batch)

        t2 = torch.zeros(B, max_nocc, max_nocc, max_nvirt, max_nvirt)
        orb_energies = torch.zeros(B, max_norb)
        mo_coeffs = torch.zeros(B, max_norb, max_nbasis)
        ao_Z = torch.zeros(B, max_nbasis)
        ao_l = torch.zeros(B, max_nbasis)

        has_z = "z_target" in batch[0]
        n_reps0 = batch[0]["n_reps"]
        if has_z:
            z_target = torch.zeros(B, n_reps0, max_norb, max_norb)
            kr_target = torch.zeros(B, n_reps0, max_norb, max_norb)
            ki_target = torch.zeros(B, n_reps0, max_norb, max_norb)
        else:
            z_target = kr_target = ki_target = None

        nocc_list, nvirt_list, norb_list, n_reps_list, names = [], [], [], [], []

        for i, s in enumerate(batch):
            no, nv, nb, nbas = s["nocc"], s["nvirt"], s["norb"], s["nbasis"]
            t2[i, :no, :no, :nv, :nv] = s["t2"]
            orb_energies[i, :nb] = s["orb_energies"]
            mo_coeffs[i, :nb, :nbas] = s["mo_coeffs"]
            ao_Z[i, :nbas] = s["ao_Z"]
            ao_l[i, :nbas] = s["ao_l"]
            if has_z:
                z_target[i, :, :nb, :nb] = s["z_target"]
                kr_target[i, :, :nb, :nb] = s["kappa_real_target"]
                ki_target[i, :, :nb, :nb] = s["kappa_imag_target"]
            nocc_list.append(no)
            nvirt_list.append(nv)
            norb_list.append(nb)
            n_reps_list.append(s["n_reps"])
            names.append(s["name"])

        out = {
            "t2": t2,
            "orb_energies": orb_energies,
            "mo_coeffs": mo_coeffs,
            "ao_Z": ao_Z,
            "ao_l": ao_l,
            "noccs": torch.tensor(nocc_list),
            "nvirts": torch.tensor(nvirt_list),
            "norbs": torch.tensor(norb_list),
            "nocc": nocc_list,
            "nvirt": nvirt_list,
            "n_reps": n_reps_list,
            "names": names,
            "max_nocc": max_nocc,
            "max_nvirt": max_nvirt,
        }
        if has_z:
            out["z_target"] = z_target
            out["kappa_real_target"] = kr_target
            out["kappa_imag_target"] = ki_target
        return out
